// Pure deterministic simulation and persistent progression. No browser dependency.
export const SLOTS=['head','chest','legs','boots','trinket1','trinket2','weapon'];
export const SLOT_NAMES={head:'头甲',chest:'胸甲',legs:'腿甲',boots:'战靴',trinket1:'饰品 I',trinket2:'饰品 II',weapon:'武器'};
export const HEROES=[
{id:'juggernaut',name:'剑圣',role:'近战 / 坦克',color:'#72d7bd',symbol:'剑',specs:['近战','坦克'],desc:'剑刃风暴席卷敌阵；坦克专精将其化为护盾，并获得吸血。',hp:770,attack:68,armor:6},
{id:'shadowfiend',name:'影魔',role:'远程爆发',color:'#ed7566',symbol:'影',specs:['远程'],desc:'魂之挽歌攻击全体敌人，每次击杀积攒灵魂。',hp:540,attack:89,armor:2},
{id:'muerta',name:'琼英碧灵',role:'远程 / 支援',color:'#7de6ce',symbol:'灵',specs:['远程','支援'],desc:'幽魂弹幕连击。支援专精链接队友，将伤害转化为治疗。',hp:580,attack:77,armor:3},
{id:'ursa',name:'拍拍熊',role:'近战 / 坦克',color:'#e7ac64',symbol:'熊',specs:['近战','坦克'],desc:'怒意随连击增长。坦克每损失20%生命触发愤怒减伤。',hp:910,attack:66,armor:5},
{id:'abaddon',name:'亚巴顿',role:'支援 / 输出',color:'#91bdeb',symbol:'霜',specs:['支援'],desc:'诅咒目标使队友攻速提高；暴击同时缠绕敌我最低生命单位。',hp:730,attack:57,armor:5},
{id:'centaur',name:'半人马',role:'坦克',color:'#d8a77c',symbol:'卫',specs:['坦克'],desc:'战争践踏击晕前排，刚毅护甲保护阵线。',hp:1050,attack:52,armor:8},
{id:'assassin',name:'幻影刺客',role:'近战 / 坦克',color:'#aaa4ed',symbol:'刃',specs:['近战','坦克'],desc:'近战幻影突袭暴击；坦克提升闪避，幻影帷幕使攻击大量落空。',hp:620,attack:86,armor:4},
{id:'oracle',name:'神谕者',role:'治疗辅助',color:'#f0d692',symbol:'谕',specs:['支援'],desc:'涤罪之焰纯粹治疗友方，命运敕令保护指定伙伴。',hp:550,attack:35,armor:2},
{id:'underlord',name:'孽主',role:'坦克 / 光环',color:'#b5cb76',symbol:'渊',specs:['坦克'],desc:'衰退光环降低敌人攻击并提升友方攻击；火雨侵蚀敌阵。',hp:960,attack:48,armor:7},
{id:'magnus',name:'猛犸',role:'坦克 / 近战',color:'#b5a3d7',symbol:'震',specs:['坦克','近战'],desc:'两极反转震击全体并眩晕，坦克专精获得额外护盾。',hp:880,attack:64,armor:6},
{id:'lina',name:'丽娜',role:'远程爆发',color:'#ff9c75',symbol:'焰',specs:['远程'],desc:'龙破斩灼烧后排；神灭斩精准终结指定敌人。',hp:520,attack:92,armor:2}
];
const byId=id=>HEROES.find(x=>x.id===id);
const clone=x=>JSON.parse(JSON.stringify(x));
function random(o){o.rng=(Math.imul(1664525,o.rng>>>0)+1013904223)>>>0;return o.rng/4294967296;}
const rarityDefs=[['普通','#a3b4bd',1],['稀有','#5cb6f3',1.45],['史诗','#bc8bf4',2],['传说','#efb968',2.7],['神器','#f2d895',3.7]];
export function createGame(seed=123){const g={version:1,rng:seed>>>0,floor:1,cleared:0,gold:200,essence:12,roster:HEROES.map((h,i)=>({id:h.id,level:1,xp:0,spec:h.specs[0],profession:['工匠','珠宝师','辩手'][i%3],equipment:{},rules:[{condition:'always',target:h.id==='oracle'?'lowest_ally':'lowest_hp',action:h.id==='oracle'?'protect':'ultimate',enabled:true}],position:i%5})),party:['centaur','juggernaut','shadowfiend','lina','oracle'],inventory:[],completed:false,battleCounter:0,settledBattles:[]};g.inventory.push(makeItem(g,'weapon',0,1),makeItem(g,'chest',0,1));return g;}
export function getStats(hero){const h=byId(hero.id)||HEROES[0];const n=Math.max(0,hero.level-1);let s={hp:h.hp+n*95,attack:h.attack+n*10,armor:h.armor+n*.55,haste:1,crit:hero.id==='assassin'?.25:hero.id==='abaddon'?.22:.08,evasion:hero.id==='assassin'?.12:0};if(hero.spec==='坦克'){s.hp*=1.28;s.attack*=.79;s.armor+=3;if(hero.id==='assassin')s.evasion=.32;}if(hero.spec==='近战')s.attack*=1.1;Object.values(hero.equipment||{}).forEach(it=>Object.entries(it.stats||{}).forEach(([k,v])=>{if(k in s)s[k]+=v;}));s.hp=Math.round(s.hp);s.attack=Math.round(s.attack);return s;}
function makeItem(g,slot,rarity=0,level=g.floor){const d=rarityDefs[rarity],n=Math.max(1,Math.ceil(level/3)),m=d[2];const stats=slot==='weapon'?{attack:Math.round((18+n*5)*m)}:slot.startsWith('trinket')?{attack:Math.round((7+n*2)*m),hp:Math.round(40*m),haste:.03*m}:slot==='boots'?{hp:Math.round(55*m),haste:.07*m}:{hp:Math.round((85+n*18)*m),armor:Math.round((1+n*.3)*m)};return {id:`item-${g.rng}-${Math.floor(random(g)*1e8)}`,name:`${['旅人','符文','永夜','王冠','星陨'][rarity]}${SLOT_NAMES[slot]}`,slot,rarity:d[0],color:d[1],level:n,stats,price:Math.round((35+n*12)*m)};}
export function generateShop(game){const g={rng:(game.floor*137+987)>>>0,floor:game.floor};return ['weapon','chest','trinket1'].map(s=>makeItem(g,s,game.floor>6?2:1));}
export function shopPrice(game,item){return Math.round(item.price*(game.party.some(id=>game.roster.find(h=>h.id===id)?.profession==='辩手')?.8:1));}
export function craftItem(g,slot){if(!SLOTS.includes(slot))return{ok:false,message:'请选择装备位置'};const cost=slot.startsWith('trinket')?5:6;if(g.essence<cost)return{ok:false,message:`需要 ${cost} 枚锻造精华`};const prof=slot.startsWith('trinket')?'珠宝师':'工匠';if(!g.party.some(id=>g.roster.find(h=>h.id===id)?.profession===prof))return{ok:false,message:`请让一位${prof}加入队伍`};g.essence-=cost;const r=random(g);const rarity=r<.08?3:r<.38?2:1;const item=makeItem(g,slot,rarity,g.floor);g.inventory.push(item);return{ok:true,message:`打造了${item.name}`,item};}
export function buyItem(g,item){if(!item||!SLOTS.includes(item.slot))return{ok:false,message:'无效装备'};const price=shopPrice(g,item);if(g.gold<price)return{ok:false,message:'金币不足'};g.gold-=price;const copy=clone(item);copy.id+=`-${g.rng}-${Math.floor(random(g)*1e8)}`;g.inventory.push(copy);return{ok:true,message:`购入${item.name}`,item:copy};}
export function equipItem(g,heroId,itemId){const h=g.roster.find(x=>x.id===heroId),i=g.inventory.findIndex(x=>x.id===itemId);if(!h||i<0)return{ok:false,message:'装备或英雄不存在'};const item=g.inventory.splice(i,1)[0];if(h.equipment[item.slot])g.inventory.push(h.equipment[item.slot]);h.equipment[item.slot]=item;return{ok:true,message:`${byId(heroId).name}装备了${item.name}`};}
export function trainHero(g,id){const h=g.roster.find(x=>x.id===id);if(!h)return{ok:false,message:'英雄不存在'};const cost=35+h.level*15;if(g.gold<cost)return{ok:false,message:`训练需要 ${cost} 金币`};if(h.level>=20)return{ok:false,message:'已达到等级上限'};g.gold-=cost;h.level++;return{ok:true,message:`${byId(id).name}升至 ${h.level} 级`};}
export function enemiesForFloor(floor){const boss=floor%3===0,scale=1+(floor-1)*.17;return Array.from({length:5},(_,i)=>{const big=boss&&i===0;return{uid:`e${i}`,id:`e${i}`,name:big?['','遗迹守望者','裂隙暴君','不朽祭司','黑曜王','永夜君主'][floor/3]:(i<2?'铁卫':i===4?'暗巫':'游魂'),team:'enemy',position:i,hp:Math.round((big?3800:i<2?1550:1200)*scale),maxHp:Math.round((big?3800:i<2?1550:1200)*scale),attack:Math.round((big?75:i===4?37:43)*scale),armor:big?9:3,haste:1,crit:.05,evasion:0,mana:i===4?40:0,maxMana:100,color:big?'#df875c':'#ad6879',symbol:big?'王':i<2?'卫':i===4?'咒':'魂',boss:big,shield:0,stun:0,cooldown:.3+i*.13,skillCooldown:0,buffs:[],rules:[],spec:'敌人',level:floor};});}
export function startBattle(g){const allies=g.party.map((id,index)=>{const h=g.roster.find(x=>x.id===id),def=byId(id),s=getStats(h);return{...clone(h),...s,uid:`a-${id}`,name:def.name,symbol:def.symbol,color:def.color,team:'ally',position:index,hp:s.hp,maxHp:s.hp,mana:25,maxMana:100,shield:0,stun:0,cooldown:.2+index*.1,skillCooldown:0,buffs:[],fury:0,threshold:0};});const debate=allies.some(x=>x.profession==='辩手');allies.forEach(x=>{if(debate){x.attack=Math.round(x.attack*1.08);x.shield=50;}if(allies.some(y=>y.id==='underlord'))x.attack=Math.round(x.attack*1.12);});const enemies=enemiesForFloor(g.floor);if(allies.some(x=>x.id==='underlord'))enemies.forEach(x=>x.attack*=.88);g.battleCounter=(g.battleCounter||0)+1;return{id:`${g.floor}-${g.battleCounter}`,floor:g.floor,seed:g.rng,rng:g.rng,units:[...allies,...enemies],time:0,events:[],status:'running',damage:{},healing:{},settled:false,accumulator:0,eventCounter:0};}
const living=(b,team)=>b.units.filter(x=>x.team===team&&x.hp>0);
function emit(b,type,source,target,amount,text){b.events.push({id:++b.eventCounter,type,source:source?.uid,target:target?.uid,amount:Math.round(amount||0),text,time:b.time});if(b.events.length>160)b.events.shift();}
function heal(b,s,t,value){if(!t||t.hp<=0)return;const amt=Math.min(value,t.maxHp-t.hp);t.hp+=amt;b.healing[s.uid]=(b.healing[s.uid]||0)+amt;emit(b,'heal',s,t,amt,`${s.name}治疗${t.name}`);}
function damage(b,s,t,value,magic=false){if(!t||t.hp<=0)return 0;if(!magic&&random(b)<t.evasion){emit(b,'miss',s,t,0,`${t.name}闪避`);return 0;}if(t.id==='assassin'&&t.spec==='坦克'&&random(b)<(t.veil>0?.7:.2)){emit(b,'miss',s,t,0,`${t.name}幻影闪避`);return 0;}let amt=value*(magic?.85:1/(1+.06*Math.max(0,t.armor)));if(t.rage>0)amt*=t.spec==='坦克'?.25:.65;if(t.protected>0)amt*=.55;if(t.id==='ursa'&&t.rage>0&&t.spec==='近战')t.attack+=value*.07;const absorb=Math.min(t.shield,amt);t.shield-=absorb;amt-=absorb;amt=Math.min(t.hp,amt);t.hp-=amt;t.mana=Math.min(100,t.mana+5);b.damage[s.uid]=(b.damage[s.uid]||0)+amt;emit(b,'damage',s,t,amt,`${s.name} → ${t.name}`);if(s.id==='juggernaut'&&s.spec==='坦克'||s.id==='assassin'&&s.spec==='坦克')heal(b,s,s,amt*.19);if(s.link){const ally=b.units.find(x=>x.uid===s.link);heal(b,s,ally,amt*.38);}if(t.id==='ursa'&&t.spec==='坦克'&&t.hp>0){const threshold=Math.min(4,Math.floor((1-t.hp/t.maxHp)*5));if(threshold>t.threshold){t.rage=[0,.5,2,3.5,5][threshold];t.threshold=threshold;emit(b,'skill',t,t,0,'愤怒守护');}}if(t.hp<=0){emit(b,'death',s,t,0,`${t.name}倒下`);if(s.id==='shadowfiend')s.attack+=12;}return amt;}
function targetFor(b,u,kind,team){const pool=living(b,team);if(!pool.length)return null;const direct=pool.find(x=>x.uid===kind||x.id===kind);if(direct)return direct;if(kind==='lowest_hp'||kind==='lowest_ally')return [...pool].sort((a,c)=>a.hp/a.maxHp-c.hp/c.maxHp)[0];if(kind==='back')return [...pool].sort((a,c)=>c.position-a.position)[0];if(kind==='strongest')return [...pool].sort((a,c)=>c.attack-a.attack)[0];return [...pool].sort((a,c)=>a.position-c.position)[0];}
function condition(b,u,c){return c==='always'||c==='low_hp'&&u.hp/u.maxHp<.45||c==='enemy_cast'&&living(b,u.team==='ally'?'enemy':'ally').some(x=>x.mana>=80);}
function activeRule(b,u,action){return(u.rules||[]).slice(0,8).find(r=>r.enabled!==false&&r.action===action&&condition(b,u,r.condition));}
function cast(b,u,enemy,ally){emit(b,'skill',u,enemy,0,skillName(u));u.mana=0;u.skillCooldown=3;const opponents=living(b,u.team==='ally'?'enemy':'ally');switch(u.id){case'oracle':heal(b,u,ally,u.attack*5+180);ally.protected=4;break;case'juggernaut':if(u.spec==='坦克'){u.shield+=u.maxHp*.3;u.protected=3;}else opponents.slice(0,3).forEach(t=>damage(b,u,t,u.attack*2,true));break;case'shadowfiend':opponents.forEach(t=>damage(b,u,t,u.attack*1.65,true));break;case'muerta':if(u.spec==='支援'){u.link=ally.uid;heal(b,u,ally,u.attack*2);}for(let i=0;i<3;i++)damage(b,u,enemy,u.attack*.9,true);break;case'ursa':if(u.spec==='近战'){u.rage=5;u.hasteBuff=5;damage(b,u,enemy,u.attack*1.8);}break;case'abaddon':heal(b,u,ally,u.attack*2.5);damage(b,u,enemy,u.attack*2,true);ally.shield+=130;break;case'centaur':opponents.filter(x=>x.position<2).forEach(t=>{damage(b,u,t,u.attack*1.5);t.stun=2;});u.shield+=140;break;case'assassin':if(u.spec==='坦克'){u.veil=5;u.shield+=100;}else damage(b,u,enemy,u.attack*4);break;case'underlord':opponents.forEach(t=>damage(b,u,t,u.attack*1.5,true));break;case'magnus':opponents.forEach(t=>{damage(b,u,t,u.attack*1.4,true);t.stun=1.5;});if(u.spec==='坦克')u.shield+=150;break;case'lina':damage(b,u,enemy,u.attack*4.1,true);break;default:if(u.position===4)heal(b,u,ally,u.attack*3+100);else{damage(b,u,enemy,u.attack*(u.boss?2.8:1.8),true);if(u.boss)enemy.stun=1;}}}
export function skillName(u){return{oracle:'命运敕令',juggernaut:u.spec==='坦克'?'剑刃壁垒':'剑刃风暴',shadowfiend:'魂之挽歌',muerta:u.spec==='支援'?'幽魂链接':'越界弹幕',ursa:'激怒',abaddon:'迷雾缠绕',centaur:'战争践踏',assassin:u.spec==='坦克'?'幻影帷幕':'恩赐解脱',underlord:'深渊火雨',magnus:'两极反转',lina:'神灭斩'}[u.id]||(u.boss?'王之震怒':u.position===4?'暗影愈合':'裂伤');}
function step(b,dt){b.time+=dt;for(const u of b.units){if(u.hp<=0)continue;for(const k of['stun','skillCooldown','rage','protected','veil','hasteBuff'])u[k]=Math.max(0,(u[k]||0)-dt);u.cooldown-=dt;u.mana=Math.min(100,u.mana+dt*3.2);if(u.stun>0)continue;const enemyTeam=u.team==='ally'?'enemy':'ally';const focus=activeRule(b,u,'focus'),ult=activeRule(b,u,'ultimate'),protect=activeRule(b,u,'protect');const enemy=targetFor(b,u,focus?.target||'front',enemyTeam);if(!enemy)break;const ally=targetFor(b,u,protect?.target||'lowest_ally',u.team);const castingRules=(u.rules||[]).filter(r=>r.enabled!==false&&(r.action==='ultimate'||r.action==='protect'));const mayCast=castingRules.length===0||ult||protect;if(u.mana>=100&&u.skillCooldown<=0&&mayCast&&!(u.id==='ursa'&&u.spec==='坦克'))cast(b,u,targetFor(b,u,ult?.target||focus?.target||'front',enemyTeam)||enemy,ally||u);if(u.cooldown<=0){u.cooldown=1.25/(u.haste*(u.hasteBuff>0?1.35:1));const crit=random(b)<u.crit;let hit=u.attack*(crit?1.8:1);if(u.id==='ursa'){u.fury=(u.fury||0)+1;hit+=u.fury*4;}damage(b,u,enemy,hit);u.mana=Math.min(100,u.mana+14);if(u.id==='oracle')heal(b,u,targetFor(b,u,protect?.target||'lowest_ally',u.team),u.attack*1.4+25);if(u.id==='abaddon'){living(b,u.team).forEach(x=>x.hasteBuff=2);if(crit){heal(b,u,targetFor(b,u,'lowest_ally',u.team),u.attack*1.4);damage(b,u,targetFor(b,u,'lowest_hp',enemyTeam),u.attack*1.4,true);}}}}if(!living(b,'enemy').length)b.status='won';else if(!living(b,'ally').length||b.time>=120)b.status='lost';}
export function tickBattle(b,dt=.1){if(b.status!=='running')return b;b.accumulator+=Math.min(2,Math.max(0,dt));let guard=0;while(b.accumulator>=.099999&&b.status==='running'&&guard++<21){b.accumulator-=.1;step(b,.1);}return b;}
export function settleBattle(g,b){if(b.status==='running'||b.settled||(g.settledBattles||[]).includes(b.id))return{ok:false,message:'战斗尚未结束或奖励已领取'};b.settled=true;g.settledBattles=(g.settledBattles||[]).concat(b.id).slice(-100);if(b.status!=='won')return{ok:true,gold:0,essence:0,xp:0,item:null,completed:false,message:'调整阵容后可免费再战'};const gold=70+b.floor*12,essence=b.floor%3===0?8:4,xp=35+b.floor*10;g.gold+=gold;g.essence+=essence;g.party.forEach(id=>{const h=g.roster.find(x=>x.id===id);h.xp+=xp;while(h.xp>=h.level*70&&h.level<20){h.xp-=h.level*70;h.level++;}});let rarity=b.floor%3===0?2:random(g)<.3?1:0;const item=makeItem(g,SLOTS[Math.floor(random(g)*SLOTS.length)],rarity,b.floor);g.inventory.push(item);let bonusItem=null;if(b.floor===9||b.floor===15){bonusItem=makeItem(g,'weapon',4,b.floor);g.inventory.push(bonusItem);}g.cleared=Math.max(g.cleared,b.floor);g.floor=Math.min(16,b.floor+1);g.completed=g.floor>15;return{ok:true,gold,essence,xp,item,bonusItem,completed:g.completed,message:g.completed?'永夜之塔已征服':'战利品已入库'};}
export function serialize(g){return JSON.stringify(g);}
export function deserialize(text){try{const g=JSON.parse(text);if(g.version!==1||!Array.isArray(g.roster)||g.roster.length!==11||!Array.isArray(g.party)||g.party.length!==5||new Set(g.party).size!==5||g.party.some(id=>!byId(id))||!Number.isFinite(g.gold)||g.gold<0||!Number.isInteger(g.floor)||g.floor<1||g.floor>16||!Array.isArray(g.inventory))return null;if(new Set(g.roster.map(h=>h.id)).size!==11)return null;for(const h of g.roster){if(!byId(h.id)||!Number.isInteger(h.level)||h.level<1||h.level>20||!Array.isArray(h.rules)||!h.equipment||Array.isArray(h.equipment)||!byId(h.id).specs.includes(h.spec)||!['工匠','珠宝师','辩手'].includes(h.profession)||!Number.isFinite(h.xp)||h.xp<0||h.rules.some(r=>!r||!['always','low_hp','enemy_cast'].includes(r.condition)||!['focus','ultimate','protect'].includes(r.action)||typeof r.target!=='string'))return null;for(const [slot,item] of Object.entries(h.equipment)){if(!SLOTS.includes(slot)||!item||item.slot!==slot||!item.stats||Object.values(item.stats).some(v=>!Number.isFinite(v)))return null;}}return g;}catch{return null;}}
